// Supabase REST API returns an array directly
const items = $input.all();
const allContacts = [];

for (const item of items) {
  // The response could be an array at the top level or nested
  const data = Array.isArray(item.json) ? item.json : (item.json.body || [item.json]);
  for (const contact of data) {
    if (contact.ghl_contact_id) {
      allContacts.push({ json: { ghl_contact_id: contact.ghl_contact_id } });
    }
  }
}

if (allContacts.length === 0) {
  return [{ json: { _no_contacts: true, synced_conversations: 0, synced_messages: 0 } }];
}

console.log(`Found ${allContacts.length} contacts to process`);
return allContacts;

// Collect all conversations from all contact responses
const allConversations = [];

for (const item of $input.all()) {
  const conversations = item.json.conversations || [];
  for (const c of conversations) {
    allConversations.push({
      json: {
        ghl_conversation_id: c.id,
        ghl_contact_id: c.contactId,
        ghl_location_id: c.locationId || null,
        type: c.type || 'sms',
        status: 'open',
        last_message_at: c.lastMessageDate || null,
        unread_count: c.unreadCount || 0,
        synced_at: new Date().toISOString(),
      }
    });
  }
}

if (allConversations.length === 0) {
  return [{ json: { _no_conversations: true, synced_conversations: 0, synced_messages: 0 } }];
}

console.log(`Found ${allConversations.length} conversations to sync`);
return allConversations;

// Collect all messages from all conversation responses
const allMessages = [];

for (const item of $input.all()) {
  const messages = item.json.messages || [];
  for (const m of messages) {
    // Determine direction
    let direction = 'outbound';
    if (m.direction === 'inbound' || m.direction === 1) {
      direction = 'inbound';
    } else if (m.direction === 'outbound' || m.direction === 2) {
      direction = 'outbound';
    }

    // Determine message type
    let type = 'sms';
    if (m.type) {
      type = String(m.type).toLowerCase();
    } else if (m.messageType === 2) {
      type = 'email';
    }

    allMessages.push({
      json: {
        ghl_message_id: m.id,
        ghl_conversation_id: m.conversationId,
        ghl_contact_id: m.contactId || null,
        direction: direction,
        type: type,
        body: m.body || null,
        status: m.status || 'delivered',
        sent_at: m.dateAdded || new Date().toISOString(),
      }
    });
  }
}

if (allMessages.length === 0) {
  return [{ json: { _no_messages: true, synced_messages: 0 } }];
}

console.log(`Found ${allMessages.length} messages to sync`);
return allMessages;

// Count items that passed through the pipeline
let syncedConversations = 0;
let syncedMessages = 0;

try {
  const convItems = $('Map Conversations').all();
  syncedConversations = convItems.filter(i => !i.json._no_conversations).length;
} catch (e) {
  // Node may not have run
}

try {
  const msgItems = $('Map Messages').all();
  syncedMessages = msgItems.filter(i => !i.json._no_messages).length;
} catch (e) {
  // Node may not have run
}

return [{
  json: {
    synced_conversations: syncedConversations,
    synced_messages: syncedMessages,
    completed_at: new Date().toISOString()
  }
}];
